#include "/workspace/shared/spectra_native_correctness_long_20261021/source/experiments/general_competition/native_cdcl.cpp"
#include <fstream>
#include <iostream>
#include <cmath>
#include <sstream>

std::vector<std::string> audit(const Solver &s, int status, std::uint64_t max_conflicts) {
  std::vector<std::string> errors;
  auto require = [&](bool ok, const char *label) { if (!ok) errors.push_back(label); };
  require(s.qhead <= s.trail.size(), "qhead_outside_trail");
  std::vector<int> positions(s.nvars + 1, -1);
  int level = 0;
  std::size_t boundary = 0;
  int previous_limit = -1;
  for (int limit : s.trail_limits) {
    require(limit >= 0 && limit > previous_limit && limit < static_cast<int>(s.trail.size()), "invalid_decision_boundary");
    previous_limit = limit;
  }
  for (std::size_t i = 0; i < s.trail.size(); ++i) {
    const int lit = s.trail[i], var = Solver::variable(lit);
    if (var < 1 || var > s.nvars) { errors.push_back("trail_literal_range"); continue; }
    require(positions[var] < 0, "duplicate_trail_variable");
    positions[var] = static_cast<int>(i);
    while (boundary < s.trail_limits.size() && s.trail_limits[boundary] <= static_cast<int>(i)) { ++level; ++boundary; }
    require(s.literal_value(lit) == 1, "trail_value_mismatch");
    require(s.levels[var] == level, "trail_level_mismatch");
  }
  for (int var = 1; var <= s.nvars; ++var) {
    require(s.values[var] >= -1 && s.values[var] <= 1, "nonboolean_value");
    require((positions[var] >= 0) == (s.values[var] != 0), "assignment_missing_from_trail");
    require(s.seen[var] == 0 && s.minimize_seen[var] == 0, "analysis_scratch_not_cleared");
    require(std::isfinite(s.activity[var]) && s.activity[var] >= 0, "invalid_activity");
    if (!s.values[var]) {
      require(s.reasons[var] == -1 && s.levels[var] == 0, "unassigned_reason_or_level");
      continue;
    }
    const int reason = s.reasons[var];
    if (reason < 0) {
      require(s.levels[var] > 0 && static_cast<std::size_t>(s.levels[var]) <= s.trail_limits.size()
        && positions[var] == s.trail_limits[s.levels[var] - 1], "nondecision_without_reason");
      continue;
    }
    if (reason >= static_cast<int>(s.clauses.size())) { errors.push_back("reason_id_range"); continue; }
    const Clause &c = s.clauses[reason];
    require(!c.deleted && !c.lits.empty(), "deleted_or_empty_reason");
    int matching = 0;
    for (int lit : c.lits) {
      const int other = Solver::variable(lit);
      if (other == var) { matching += s.literal_value(lit) == 1; continue; }
      require(s.literal_value(lit) == -1, "reason_antecedent_not_false");
      require(positions[other] >= 0 && positions[other] < positions[var], "reason_antecedent_not_earlier");
    }
    require(matching == 1, "reason_missing_implied_literal");
  }
  std::vector<int> w0(s.clauses.size(), 0), w1(s.clauses.size(), 0);
  for (std::size_t slot = 0; slot < s.watches.size(); ++slot) {
    for (int id : s.watches[slot]) {
      if (id < 0 || id >= static_cast<int>(s.clauses.size())) { errors.push_back("watch_id_range"); continue; }
      const Clause &c = s.clauses[id];
      if (c.deleted) continue; // Lazy deleted entries need not be live registrations.
      if (c.watch0 < 0 || c.watch1 < 0 || c.watch0 >= static_cast<int>(c.lits.size()) || c.watch1 >= static_cast<int>(c.lits.size())) {
        errors.push_back("watch_position_range"); continue;
      }
      if (s.watch_index(c.lits[c.watch0]) == slot) ++w0[id];
      else if (c.watch1 != c.watch0 && s.watch_index(c.lits[c.watch1]) == slot) ++w1[id];
      else errors.push_back("live_stale_watch");
    }
  }
  std::uint64_t learned = 0, deleted = 0;
  for (std::size_t id = 0; id < s.clauses.size(); ++id) {
    const Clause &c = s.clauses[id];
    learned += c.learned; deleted += c.deleted;
    if (c.deleted) { require(c.learned, "deleted_original_clause"); continue; }
    require(!c.lits.empty(), "live_empty_clause");
    require(w0[id] == 1 && w1[id] == (c.watch0 != c.watch1), "watch_registration_count");
    require(c.lits.size() == 1 || c.watch0 != c.watch1, "duplicate_nonunit_watch_position");
    for (int lit : c.lits) require(s.occurs[Solver::variable(lit)] != 0, "clause_variable_not_relevant");
  }
  require(learned == s.stats.learned_clauses && deleted == s.stats.deleted_clauses, "clause_statistics_mismatch");
  auto heap = s.variable_heap;
  std::vector<int> valid_entries(s.nvars + 1, 0);
  while (!heap.empty()) {
    const HeapEntry entry = heap.top(); heap.pop();
    const int var = -entry.negative_variable;
    if (var < 1 || var > s.nvars) { errors.push_back("heap_variable_range"); continue; }
    if (entry.generation == s.heap_generation[var] && entry.activity == s.activity[var]) ++valid_entries[var];
  }
  for (int var = 1; var <= s.nvars; ++var) {
    if (s.occurs[var] && !s.values[var]) require(valid_entries[var] > 0, "unassigned_relevant_variable_missing_from_heap");
  }
  std::uint64_t proof_literals = 0, proof_nonempty = 0, proof_empty = 0;
  for (const auto &c : s.proof) { proof_literals += c.size(); proof_nonempty += !c.empty(); proof_empty += c.empty(); }
  require(proof_nonempty == s.stats.learned_clauses && proof_literals == s.stats.learned_literals, "proof_statistics_mismatch");
  require(proof_empty == (status == 20 ? 1u : 0u), "empty_proof_clause_status_mismatch");
  require(status != 20 || (!s.proof.empty() && s.proof.back().empty()), "refutation_not_terminated");
  if (status == 1 || status == 2) require(s.stats.conflicts == s.stats.learned_clauses + 1, "unknown_conflict_statistics");
  if (status == 1) {
    require(max_conflicts < std::numeric_limits<std::uint64_t>::max() && s.stats.conflicts == max_conflicts + 1, "conflict_budget_termination");
    require(s.decision_level() > 0, "budget_conflict_at_root");
    bool conflict = false;
    for (const Clause &c : s.clauses) {
      if (c.deleted) continue;
      bool falsified = true;
      for (int lit : c.lits) falsified &= s.literal_value(lit) < 0;
      conflict |= falsified;
    }
    require(conflict, "conflict_budget_without_conflict");
  }
  if (status == 20) require(s.decision_level() == 0, "unsat_above_root");
  if (status == 10) {
    require(s.qhead == s.trail.size(), "sat_propagation_incomplete");
    require(s.stats.conflicts == s.stats.learned_clauses, "sat_conflict_statistics");
    for (int var = 1; var <= s.nvars; ++var) require(!s.occurs[var] || s.values[var], "sat_relevant_variable_unassigned");
    for (const Clause &c : s.clauses) {
      if (c.deleted) continue;
      bool satisfied = false;
      for (int lit : c.lits) satisfied |= s.literal_value(lit) > 0;
      require(satisfied, "sat_live_clause_unsatisfied");
    }
  }
  std::sort(errors.begin(), errors.end());
  errors.erase(std::unique(errors.begin(), errors.end()), errors.end());
  return errors;
}

int main(int argc, char **argv) {
  try {
    if (argc != 7) throw std::invalid_argument("input proof state model max_conflicts max_learned_literals required");
    std::ifstream input(argv[1]);
    input.exceptions(std::ios::badbit);
    std::string p, cnf; int nvars; std::size_t count;
    if (!(input >> p >> cnf >> nvars >> count) || p != "p" || cnf != "cnf" || nvars < 0 || nvars > 10000000) throw std::runtime_error("bad canonical header");
    Solver solver(nvars);
    for (std::size_t row = 0; row < count; ++row) {
      std::vector<int> lits; int lit;
      do { if (!(input >> lit)) throw std::runtime_error("truncated canonical row"); if (lit) lits.push_back(lit); } while (lit);
      const int dummy = 0;
      const int *begin = lits.empty() ? &dummy : lits.data();
      solver.add_initial(begin, begin + lits.size());
    }
    std::string extra; if (input >> extra) throw std::runtime_error("trailing canonical data");
    solver.initialize_heap();
    const int status = solver.solve(std::stoull(argv[5]), std::stoull(argv[6]));
    std::ofstream proof(argv[2]); proof.exceptions(std::ios::badbit | std::ios::failbit);
    for (const auto &c : solver.proof) { for (int lit : c) proof << lit << ' '; proof << "0\n"; }
    proof.close();
    std::ofstream model(argv[4]); model.exceptions(std::ios::badbit | std::ios::failbit);
    if (status == 10) { for (int var = 1; var <= nvars; ++var) model << (solver.values[var] > 0 ? var : -var) << ' '; model << "0\n"; }
    model.close();
    const auto errors = audit(solver, status, std::stoull(argv[5]));
    std::ofstream state(argv[3]); state.exceptions(std::ios::badbit | std::ios::failbit);
    const Stats &s = solver.stats;
    std::size_t zero_relevant = 0;
    for (int var = 1; var <= nvars; ++var) zero_relevant += solver.occurs[var] && solver.activity[var] == 0.0;
    state << "{\"status\":" << status << ",\"decisions\":" << s.decisions << ",\"propagations\":" << s.propagations << ",\"conflicts\":" << s.conflicts
      << ",\"restarts\":" << s.restarts << ",\"learned_clauses\":" << s.learned_clauses << ",\"learned_literals\":" << s.learned_literals
      << ",\"reductions\":" << s.reductions << ",\"deleted_clauses\":" << s.deleted_clauses << ",\"proof_clauses\":" << solver.proof.size()
      << ",\"trail_size\":" << solver.trail.size() << ",\"decision_level\":" << solver.decision_level() << ",\"qhead\":" << solver.qhead
      << ",\"zero_activity_relevant_variables\":" << zero_relevant << ",\"invariant_errors\":[";
    for (std::size_t i = 0; i < errors.size(); ++i) state << (i ? "," : "") << '"' << errors[i] << '"';
    state << "]}\n"; state.close();
    return errors.empty() ? 0 : 3;
  } catch (const std::exception &error) { std::cerr << error.what() << '\n'; return 4; }
}
